// Bakes the Voxel Pagoda Garden into a .kumo scene file.
//
// The scene is generated by the same JavaScript that drives the web version (src/), then all
// geometry is written into one vertex/index blob and everything else (lights, particles, sky
// keyframes, animation parameters) into a JSON manifest. The engine never runs this code.
//
//   node bake.mjs ../../assets/pagoda.kumo
//
// File layout: "KUMO" | u32 version | u32 jsonLen | json (padded to 4) | u32 binLen | bin
// Vertex (20 bytes): f32 x,y,z | i8 nx,ny,nz,flags | u8 r,g,b,a
//   rgb = sRGB-encoded albedo (ambient occlusion baked in), a = wind sway (0..255)
//   flags: bit0 = glowing voxel. For the waterfall rgb carries the uv instead.

import * as THREE from 'three';
import { writeFileSync } from 'node:fs';
import { meshGrid, mulberry32 } from './src/voxels.js';
import { buildGarden, buildMiniIsland, buildCloud, WATER_Y, SURF, POND } from './src/garden.js';
import { createWater, Waterfall, Koi, LilyPads, Petals, Fireflies } from './src/effects.js';
import { RAW } from './src/sky.js';

const out = process.argv[2] || 'pagoda.kumo';
const lin = (hex) => { const c = new THREE.Color(hex); return [c.r, c.g, c.b]; };
const r4 = (v) => Math.round(v * 1e4) / 1e4;
const v3 = (a) => a.map(r4);

// ---------------------------------------------------------------- geometry blob

const verts = [];   // packed later
const indices = [];
const meshes = [];

const toSrgb = (c) => (c <= 0.0031308 ? c * 12.92 : 1.055 * Math.pow(c, 1 / 2.4) - 0.055);
const u8 = (v) => Math.max(0, Math.min(255, Math.round(v * 255)));
const i8 = (v) => Math.max(-127, Math.min(127, Math.round(v * 127)));

function beginMesh(name) {
  const m = { name, firstVertex: verts.length, vertexCount: 0, firstIndex: indices.length, indexCount: 0 };
  meshes.push(m);
  return m;
}

function endMesh(m) {
  m.vertexCount = verts.length - m.firstVertex;
  m.indexCount = indices.length - m.firstIndex;
  return meshes.length - 1;
}

// Appends a three.js geometry (positions relative to the current mesh's first vertex).
function addGeometry(m, geo, { glow = false, matrix = null, color = null, uvAsColor = false } = {}) {
  if (!geo) return;
  const pos = geo.attributes.position, nor = geo.attributes.normal, col = geo.attributes.color;
  const sway = geo.attributes.aSway, uv = geo.attributes.uv;
  const base = verts.length - m.firstVertex;
  const p = new THREE.Vector3(), n = new THREE.Vector3();
  const nm = matrix ? new THREE.Matrix3().getNormalMatrix(matrix) : null;
  for (let i = 0; i < pos.count; i++) {
    p.fromBufferAttribute(pos, i);
    if (matrix) p.applyMatrix4(matrix);
    if (nor) { n.fromBufferAttribute(nor, i); if (nm) n.applyMatrix3(nm).normalize(); } else n.set(0, 1, 0);
    let rgb;
    if (uvAsColor) rgb = [uv.getX(i), uv.getY(i), 0];
    else if (col) rgb = [toSrgb(col.getX(i)), toSrgb(col.getY(i)), toSrgb(col.getZ(i))];
    else if (color) rgb = color.map(toSrgb);
    else rgb = [1, 1, 1];
    verts.push({ p: [p.x, p.y, p.z], n: [i8(n.x), i8(n.y), i8(n.z), glow ? 1 : 0], c: [u8(rgb[0]), u8(rgb[1]), u8(rgb[2]), sway ? u8(sway.getX(i)) : 0] });
  }
  if (geo.index) for (let i = 0; i < geo.index.count; i++) indices.push(base + geo.index.getX(i));
  else for (let i = 0; i < pos.count; i++) indices.push(base + i);
}

function addVoxelGrid(name, grid, translate = null) {
  const m = beginMesh(name);
  const [s, w, g] = meshGrid(grid);
  for (const [geo, glow] of [[s, false], [w, false], [g, true]]) {
    if (!geo) continue;
    if (translate) geo.translate(...translate);
    addGeometry(m, geo, { glow });
  }
  return endMesh(m);
}

// ---------------------------------------------------------------- world (same order as the web version)

const fakeScene = { added: [], add(...o) { this.added.push(...o); } };

const { grid, info } = buildGarden();
const objects = [];
const islandMesh = addVoxelGrid('island', grid);
objects.push({ mesh: islandMesh, cast: true, receive: true, emissive: [0, 0, 0] });

const water = createWater(info.water);
const waterMesh = (() => { const m = beginMesh('water'); addGeometry(m, water.mesh.geometry); return endMesh(m); })();

const waterfall = new Waterfall(fakeScene, info.waterfall);
const fallMesh = (() => { const m = beginMesh('waterfall'); addGeometry(m, waterfall.mesh.geometry, { uvAsColor: true }); return endMesh(m); })();

const koi = new Koi(fakeScene);
const swimmers = koi.fish.map((f, i) => {
  const m = beginMesh(`koi${i}`);
  addGeometry(m, f.m.geometry);
  return {
    mesh: endMesh(m), scale: v3([f.m.scale.x, f.m.scale.y, f.m.scale.z]),
    center: [POND.cx, POND.cz], th: r4(f.th), w: r4(f.w), rx: r4(f.rx), rz: r4(f.rz),
    ph: r4(f.ph), ox: r4(f.ox), oz: r4(f.oz), y: r4(f.y),
  };
});

const before = fakeScene.added.length;
new LilyPads(fakeScene, info);
const [pads, flowers] = fakeScene.added.slice(before);
for (const [inst, name, emissive, receive] of [[pads, 'lilypads', [0, 0, 0], true], [flowers, 'lilyflowers', lin(0x401828), false]]) {
  const m = beginMesh(name);
  const mat = new THREE.Matrix4(), c = new THREE.Color();
  for (let i = 0; i < inst.count; i++) {
    inst.getMatrixAt(i, mat);
    if (mat.elements.every((v, k) => v === new THREE.Matrix4().elements[k])) continue; // never placed
    inst.getColorAt(i, c);
    addGeometry(m, inst.geometry, { matrix: mat, color: [c.r, c.g, c.b] });
  }
  objects.push({ mesh: endMesh(m), cast: false, receive, emissive: v3(emissive) });
}

new Petals(fakeScene, info.spawns, () => -999); // keeps the random sequence identical
const fireflies = new Fireflies(fakeScene, info);

// glow sprites + point lights
const glows = [];
for (const l of info.lanterns) glows.push({ pos: v3([l.x, l.y, l.z]), size: 5, color: v3(lin(0xffb259)), strength: 1 });
for (const w of info.windows) glows.push({ pos: v3([w.x, w.y, w.z]), size: w.s, color: v3(lin(0xff9d45)), strength: 0.7 });
const lights = [info.lanterns[0], info.lanterns[1], info.lanterns[2], info.doorLight].map((p, i) => ({
  pos: v3([p.x, p.y + 0.5, p.z]), color: v3(lin(0xffa64d)), intensity: i === 3 ? 30 : 22, distance: 22, decay: 1.6,
}));

// mini islands
[
  ['sakura', 501, [-50, 6, 22], 1.0],
  ['lantern', 502, [46, 16, -30], 0.9],
  ['shrine', 503, [-38, -16, -46], 1.0],
  ['sakura', 504, [44, -10, 40], 0.75],
].forEach(([type, seed, p, s]) => {
  const mi = buildMiniIsland(type, seed);
  const obj = objects.length;
  objects.push({
    mesh: addVoxelGrid(`mini_${type}_${seed}`, mi.grid), cast: false, receive: true, emissive: [0, 0, 0],
    pos: p, scale: [s, s, s],
    bob: { amp: 1.4, speed: 0.35, phase: r4(seed * 1.7), rotAmp: 0.4, rotSpeed: 0.05 },
  });
  for (const l of mi.lanterns) glows.push({ pos: v3([p[0] + l.x * s, p[1] + l.y * s, p[2] + l.z * s]), size: 4 * s, color: v3(lin(0xffb259)), strength: 1, follow: obj, local: v3([l.x, l.y, l.z]) });
});

// clouds
const cr = mulberry32(77);
const CLOUD_LAYERS = [
  { n: 9, r: [250, 400], y: [-30, 70], s: [3.2, 5], speed: 0.006 },
  { n: 6, r: [58, 125], y: [-34, -48], s: [2, 2.9], speed: 0.01 },
  { n: 6, r: [0, 170], y: [-80, -100], s: [3.5, 5.5], speed: 0.004 },
];
let ci = 0;
for (const L of CLOUD_LAYERS) {
  for (let i = 0; i < L.n; i++, ci++) {
    const c = buildCloud(900 + ci, 12 + Math.floor(cr() * 12));
    const mesh = addVoxelGrid(`cloud${ci}`, c.grid, [-c.w / 2, 0, -c.d / 2]);
    const s = L.s[0] + cr() * (L.s[1] - L.s[0]);
    const rotY = cr() * Math.PI;
    const a = (i / L.n) * Math.PI * 2 + cr() * 0.6;
    const r = L.r[0] + cr() * (L.r[1] - L.r[0]);
    const y = L.y[0] + cr() * (L.y[1] - L.y[0]);
    const speed = L.speed * (0.6 + cr() * 0.8);
    objects.push({
      mesh, cast: false, receive: false, emissive: v3(lin(0x1a1e28)), fog: true,
      scale: v3([s, s * 0.8, s]), rotY: r4(rotY),
      orbit: { angle: r4(a), radius: r4(r), y: r4(y), speed: r4(speed * 1e4) / 1e4, wobble: 1.5 },
    });
  }
}

// landing heights for petals (same rule as groundAt in the web version)
const H = new Array(info.half * 2 * info.half * 2);
for (let i = 0; i < H.length; i++) {
  H[i] = info.H[i] < -100 ? -999 : info.surf[i] === SURF.WATER ? WATER_Y : info.H[i] + 1;
}

const fa = fireflies.sys.geo.attributes.aSize.array;
const manifest = {
  version: 1,
  title: 'Voxel Pagoda Garden',
  camera: { target: [0, 10, 2], fov: 30, near: 1, far: 2000, angle: 0.55, elev: 0.3, fit: [53, 60], orbitSpeed: 0.028 },
  fog: { near: 160, far: 520 },
  shadow: { size: 2048, extent: 58, near: 10, far: 360, target: [0, 8, 0], distance: 180, bias: -0.0004, normalBias: 0.06 },
  sky: {
    keys: RAW.map(([h, k]) => ({
      h, zen: v3(lin(k.zen)), hor: v3(lin(k.hor)), gnd: v3(lin(k.gnd)), keyC: v3(lin(k.keyC)),
      hemiS: v3(lin(k.hemiS)), hemiG: v3(lin(k.hemiG)),
      key: k.key, hemiI: k.hemiI, glow: k.glow, stars: k.stars, exp: k.exp,
    })),
    sun: { rise: 6, set: 19, tilt: 0.95, yaw: 0.35 },
    moon: { tilt: 0.75, yaw: -0.25 },
  },
  objects,
  swimmers,
  water: { mesh: waterMesh, deep: v3(lin(0x1f6f7a)), shallow: v3(lin(0x52b8b2)), glow: v3(lin(0xffb35a)) },
  waterfall: { mesh: fallMesh, ...info.waterfall, color: v3(lin(0x8fd3e8)), spray: v3(lin(0xeaf6ff)) },
  petals: {
    count: 520, max: 1000, size: [0.36, 0.28], emissive: v3(lin(0x2a1018)),
    colors: [0xffd6e4, 0xf9b9d0, 0xffe8f0, 0xf5a6c4, 0xfcc8da].map((h) => v3(lin(h))),
    spawns: info.spawns.map(v3),
  },
  ground: { half: info.half, heights: H.map((v) => Math.round(v * 100) / 100) },
  fireflies: {
    color: v3(lin(0xd9ff7a)),
    items: Array.from({ length: fireflies.n }, (_, i) => v3([fireflies.base[i * 3], fireflies.base[i * 3 + 1], fireflies.base[i * 3 + 2], fireflies.ph[i], fa[i]])),
  },
  glows,
  lights,
  meshes,
};

// ---------------------------------------------------------------- write

const json = Buffer.from(JSON.stringify(manifest));
const jsonPad = (4 - (json.length % 4)) % 4;
const binLen = verts.length * 20 + indices.length * 4;
const buf = Buffer.alloc(16 + json.length + jsonPad + binLen);
let o = 0;
buf.write('KUMO', o); o += 4;
buf.writeUInt32LE(1, o); o += 4;
buf.writeUInt32LE(json.length + jsonPad, o); o += 4;
json.copy(buf, o); o += json.length;
buf.fill(0x20, o, o + jsonPad); o += jsonPad;
buf.writeUInt32LE(binLen, o); o += 4;
for (const v of verts) {
  buf.writeFloatLE(v.p[0], o); buf.writeFloatLE(v.p[1], o + 4); buf.writeFloatLE(v.p[2], o + 8);
  for (let k = 0; k < 4; k++) buf.writeInt8(v.n[k], o + 12 + k);
  for (let k = 0; k < 4; k++) buf.writeUInt8(v.c[k], o + 16 + k);
  o += 20;
}
for (const i of indices) { buf.writeUInt32LE(i, o); o += 4; }
writeFileSync(out, buf);

const mb = (b) => (b / 1048576).toFixed(2);
console.log(`${out}: ${meshes.length} meshes, ${verts.length} vertices, ${indices.length / 3} triangles, ` +
  `${objects.length} objects, ${glows.length} glows, ${info.spawns.length} petal spawns`);
console.log(`size ${mb(buf.length)} MB (json ${mb(json.length)} MB, geometry ${mb(binLen)} MB)`);
